code.source:
#include <stdio.h>

int add(int a, int b) { return a + b; }
int sub(int a, int b) { return a - b; }

int apply(int (*op)(int, int), int x, int y) {
    return op(x, y);
}

int main(void) {
    int (*f)(int, int) = add;
    printf("f(8, 3) = %d\n", f(8, 3));

    f = sub;
    printf("f(8, 3) = %d\n", f(8, 3));

    printf("apply(add, 10, 4) = %d\n", apply(add, 10, 4));
    printf("apply(sub, 10, 4) = %d\n", apply(sub, 10, 4));
    return 0;
}

